// MatrixScannerApp.java
public class MatrixScannerApp {
    public static void main(String[] args) {
        // 3x4 grid representing satellite telemetry sensor cells
        int[][] sensorGrid = {
            { 10,  12,  14,  15 },
            { 18,  99,  22,  24 }, // 99 is anomaly target
            { 30,  32,  34,  36 }
