                System.out.println("Identified Dog! Triggering action:");
                d.fetch();
            } else if (a instanceof Cat c) {
                System.out.println("Identified Cat! Ready for nap.");
            } else {
                System.out.println("Identified Unknown Animal type.");
            }
        }
    }
}
