    <dependencies>
        <dependency>
            <groupId>org.slf4j</groupId>
            <artifactId>slf4j-api</artifactId>
            <version>2.0.12</version>
            <scope>compile</scope> <!-- compile, test, runtime, provided -->
        </dependency>
    </dependencies>
</project>
